<script setup>
import FoodImageSlot from './FoodImageSlot.vue'
import AppIcon from './AppIcon.vue'
import { computed,ref } from 'vue'
import { onShow,onHide,onUnload } from '@dcloudio/uni-app'
import { request } from '../services/request.js'
import { sessionRevision } from '../services/session.js'
import { scopedStorage } from '../services/storage.js'
import { newHealthRequestId } from '../services/health-task-flow.js'
import { mealDay,mealLabels,readDietRecord,feedbackUrl,portionNote } from '../services/cloud-meals.js'
import { mealInput } from '../services/health-meal-input.js'
import HealthMealEditor from './HealthMealEditor.vue'
const props=defineProps({detailId:String,memberId:String})
const members=ref([]),records=ref([]),scope=ref('all'),date=ref(mealDay(new Date().toISOString())),busy=ref(false),error=ref(''),detail=ref(null),editing=ref(false),meal=ref(null),reason=ref(''),next=ref({}),pending=ref(null),recipes=ref([])
const visible=computed(()=>records.value.filter(r=>mealDay(r.snapshot.meal.eaten_at)===date.value&&(scope.value==='all'||r.member_id===scope.value)))
let epoch=0
const name=id=>{const m=members.value.find(m=>m.id===id);return m?.display_name||m?.name||m?.relationship_label||'成员'}
function hide(){epoch++;members.value=[];records.value=[];detail.value=null;meal.value=null;editing.value=false;busy.value=false;error.value='';pending.value=null;next.value={};recipes.value=[];scope.value='all'}
function failure(e,mine,rev){if(mine!==epoch)return;if(rev!==sessionRevision()||[401,403,404,410].includes(Number(e.code))||e.code==='SESSION_CHANGED'){hide();error.value='当前成员授权或记录来源已变化，请重新读取。'}else error.value=e.message}
async function load(more=false){if(busy.value)return;const mine=++epoch,rev=sessionRevision(),current=()=>mine===epoch&&rev===sessionRevision();busy.value=true;error.value='';try{
 if(!members.value.length){const {data}=await request({path:'/api/health/v1/members'});if(!current())return;members.value=data.filter(m=>m.scopes?.includes('diet_edit'));if(props.memberId&&!members.value.some(m=>m.id===props.memberId))throw new Error('该成员当前未授权读取饮食记录');if(props.memberId)scope.value=props.memberId}
 if(!more){records.value=[];next.value={};recipes.value=[]}
 const selected=scope.value==='all'?members.value:members.value.filter(m=>m.id===scope.value)
 for(const m of selected){const offset=more?next.value[m.id]:0;if(offset==null&&more)continue;const {data}=await request({path:`/api/health/v1/members/${m.id}/diet-logs/page?limit=50&offset=${offset}`});if(!current())return;if(!Array.isArray(data.records))throw new Error('饮食记录返回不完整');records.value=[...records.value.filter(r=>!data.records.some(n=>n.id===r.id)),...data.records.map(r=>({...r,member_id:m.id}))];next.value={...next.value,[m.id]:data.next_offset}}
 if(detail.value||props.detailId){const member=detail.value?.member_id||props.memberId,id=detail.value?.id||props.detailId;if(!member)throw new Error('此旧链接缺少成员信息，请从饮食记录列表重新打开');const fresh=await readDietRecord(member,id);if(!current())return;detail.value=fresh;date.value=mealDay(fresh.snapshot.meal.eaten_at);editing.value=false}
 }catch(e){failure(e,mine,rev)}finally{if(mine===epoch)busy.value=false}}
function select(id){if(busy.value)return;scope.value=id;void load()}
async function show(row){if(busy.value)return;const mine=++epoch,rev=sessionRevision();busy.value=true;error.value='';detail.value=null;editing.value=false;try{const data=await readDietRecord(row.member_id,row.id);if(mine===epoch&&rev===sessionRevision()){detail.value=data;pending.value=scopedStorage.getStorageSync('meal-correction:'+row.id)||null}}catch(e){failure(e,mine,rev)}finally{if(mine===epoch)busy.value=false}}
function edit(){meal.value=JSON.parse(JSON.stringify(detail.value.snapshot.meal));reason.value='';editing.value=true}
async function save(){if(busy.value||(!pending.value&&!reason.value.trim()))return;const mine=++epoch,rev=sessionRevision();busy.value=true;error.value='';const source=detail.value;try{if(!pending.value){const id=newHealthRequestId();pending.value={path:'/api/health/v1/diet-logs/'+source.id,method:'PATCH',headers:{'Idempotency-Key':id,'If-Match':'"'+source.source_version+'"'},data:{expected_version:source.source_version,client_request_id:id,meal:mealInput(meal.value),reason:reason.value.trim(),accept_incomplete:true}};scopedStorage.setStorageSync('meal-correction:'+source.id,pending.value)}await request(pending.value);if(mine!==epoch||rev!==sessionRevision())return;pending.value=null;scopedStorage.setStorageSync('meal-correction:'+source.id,null);const fresh=await readDietRecord(source.member_id,source.id);if(mine!==epoch||rev!==sessionRevision())return;detail.value=fresh;editing.value=false;records.value=records.value.map(r=>r.id===source.id?detail.value:r)}catch(e){if(mine===epoch){if(rev!==sessionRevision()||[401,403,404,410].includes(Number(e.code))||e.code==='SESSION_CHANGED'){failure(e,mine,rev);return}error.value=e.message;if([400,404,409,422].includes(Number(e.code))){pending.value=null;scopedStorage.setStorageSync('meal-correction:'+source.id,null)}if(Number(e.code)===409){try{const fresh=await readDietRecord(source.member_id,source.id);if(mine!==epoch||rev!==sessionRevision())return;detail.value=fresh;editing.value=false;error.value='记录已变化，已读取当前版本；请重新核对后再修改。'}catch(readError){if(mine===epoch&&rev===sessionRevision()){detail.value=null;error.value=readError.message}}}}}finally{if(mine===epoch)busy.value=false}}
async function searchRecipes(query=''){if(busy.value)return;const mine=++epoch,rev=sessionRevision();busy.value=true;error.value='';try{const {data}=await request({path:'/api/health/v1/recipes?q='+encodeURIComponent(query)});if(mine===epoch&&rev===sessionRevision())recipes.value=data}catch(e){failure(e,mine,rev)}finally{if(mine===epoch)busy.value=false}}
function chat(row=detail.value){uni.navigateTo({url:feedbackUrl(row.member_id,row)})}
onShow(()=>load());onHide(hide);onUnload(hide)

const eatenWeight=item=>item.grams==null||item.share_ratio==null?'重量未知':Number((Number(item.grams)*Number(item.share_ratio)).toFixed(1))+' g'
const dayLabel=value=>{const match=/^\d{4}-(\d{2})-(\d{2})$/.exec(value||'');return match?Number(match[1])+'月'+Number(match[2])+'日':value}
</script>
<template>

 <view class="journal" :class="{'is-editing':editing}">
  <view class="journal-heading"><text>{{editing?'调整这一餐':detail?'这一餐，已记下':'每一餐，都记得'}}</text></view>
  <text v-if="busy" class="journal-loading">正在读取…</text><view v-if="error" class="journal-error" role="alert"><text>{{error}}</text><button :disabled="busy" @click="load()">重新读取</button></view>
  <template v-if="!detail"><view class="journal-toolbar"><picker mode="date" :value="date" @change="date=$event.detail.value"><view class="journal-date"><AppIcon name="calendar" :size="32"/><text>{{dayLabel(date)}} </text><text>⌄</text></view></picker><button @click="uni.navigateTo({url:'/pages/scan/index'})">记一餐 ＋</button></view><scroll-view scroll-x class="scope-tabs"><view class="scope-row"><button :class="{active:scope==='all'}" :disabled="busy" @click="select('all')">全家</button><button v-for="m in members" :key="m.id" :class="{active:scope===m.id}" :disabled="busy" @click="select(m.id)">{{name(m.id)}}</button></view></scroll-view>
   <view class="meal-list"><view v-for="(label,key) in mealLabels" :key="key" class="meal-card"><view class="meal-head"><text>{{label}}</text><text>{{visible.some(r=>r.snapshot.meal.meal_type===key)?'已记录':'未记录'}}</text></view><button v-for="r in visible.filter(r=>r.snapshot.meal.meal_type===key)" :key="r.id" class="record-row" :disabled="busy" @click="show(r)"><FoodImageSlot class="record-image"/><view class="record-copy"><text>{{r.snapshot.meal.items.filter(i=>!i.excluded).map(i=>i.name).join(' · ')}}</text><text>{{name(r.member_id)}} · {{portionNote(r.snapshot.meal.items[0]||{})}}</text></view><text class="record-chevron">›</text></button></view></view><button v-if="Object.values(next).some(n=>n!==null)" class="journal-more" :disabled="busy" @click="load(true)">加载更早记录</button>
  </template>
  <template v-else><view class="record-summary"><text>{{name(detail.member_id)}} · {{mealLabels[detail.snapshot.meal.meal_type]}}</text><text>{{dayLabel(mealDay(detail.snapshot.meal.eaten_at))}}</text></view>
   <template v-if="editing"><HealthMealEditor :meal="meal" :coarse="true" :disabled="busy||!!pending" :recipes="recipes" @search="searchRecipes"/><view class="correction-reason"><text>更正原因</text><textarea v-model="reason" :disabled="busy||!!pending" class="text-area" placeholder="例如：调整了实际吃过的份量"/></view><view class="journal-savebar"><button class="cancel-edit" :disabled="busy||!!pending" @click="editing=false">取消</button><button class="save-correction" :disabled="busy||(!pending&&!reason.trim())" @click="save">{{busy?'正在保存…':pending?'恢复原保存请求':'确认更正并保存'}}</button></view></template>
   <template v-else><view class="record-dishes"><view v-for="item in detail.snapshot.meal.items.filter(i=>!i.excluded)" :key="item.item_id" class="detail-item"><FoodImageSlot class="record-image"/><view><text>{{item.name}}</text><text>{{portionNote(item)}} · {{eatenWeight(item)}}</text></view></view></view><view class="record-nutrition"><text>热量</text><text>{{detail.snapshot.nutrition?.totals?.energy_kcal??'未知'}}<text v-if="detail.snapshot.nutrition?.totals?.energy_kcal!=null"> kcal</text></text></view><view class="record-actions"><button class="primary-button" :disabled="busy||!!pending" @click="chat()">聊聊这一餐</button><button v-if="pending" class="secondary-button" :disabled="busy" @click="save">恢复上次更正请求</button><button v-else class="secondary-button" :disabled="busy" @click="edit">更正这条记录</button><button class="journal-more" :disabled="busy||!!pending" @click="detail=null;editing=false">返回记录列表</button></view></template>
  </template>
 </view>
</template>
<style scoped>

.journal{padding-bottom:32rpx;color:#252b35}.journal.is-editing{padding-bottom:calc(env(safe-area-inset-bottom) + 180rpx)}.journal-heading{padding:32rpx 4rpx 28rpx;font-size:48rpx;font-weight:500;line-height:1.35}.journal-loading{display:block;font-size:27rpx;color:#65728c;margin:16rpx 0}.journal-error{padding:24rpx;margin:16rpx 0;background:#fff5f3;border-radius:22rpx;font-size:27rpx;line-height:1.7;color:#b83532}.journal-error button{color:#0674ed;min-height:44px}.journal-toolbar{display:flex;justify-content:space-between;align-items:center;gap:18rpx;margin:8rpx 0 24rpx}.journal-toolbar .journal-date{display:flex;align-items:center;gap:12rpx;min-height:44px;font-size:29rpx}.journal-toolbar .journal-date>text:last-child{color:#65728c}.journal-toolbar>button{display:flex;align-items:center;justify-content:center;min-height:44px;padding:12rpx 26rpx;font-size:27rpx;border-radius:999rpx;color:#fff;background:#25262a}.scope-tabs{white-space:nowrap;margin-bottom:22rpx}.scope-row{display:flex;gap:12rpx}.scope-row button{flex-shrink:0;min-height:44px;padding:10rpx 26rpx;border:1rpx solid #e7ebf2;border-radius:999rpx;font-size:27rpx;background:#fff;color:#65728c}.scope-row .active{border-color:#c5ddff;color:#0674ed;background:#edf5ff}.meal-card{padding:24rpx;margin-bottom:18rpx;border:1rpx solid #e7ebf2;border-radius:26rpx;background:#fff}.meal-head{display:flex;justify-content:space-between;gap:20rpx;align-items:center;font-size:29rpx;font-weight:500;min-height:48rpx}.meal-head>text:last-child{color:#65728c;font-size:25rpx;font-weight:400}.record-row{display:flex;align-items:center;gap:20rpx;padding-top:22rpx;width:100%;text-align:left}.record-image{width:112rpx;height:112rpx;border-radius:18rpx}.record-copy{flex:1;min-width:0}.record-copy>text{display:block;font-size:29rpx;line-height:1.6;overflow-wrap:anywhere}.record-copy>text+text{font-size:26rpx;color:#65728c;margin-top:8rpx}.record-chevron{color:#65728c;font-size:34rpx}.journal-more{width:100%;min-height:44px;font-size:27rpx;color:#0674ed;margin-top:16rpx}.record-summary{display:flex;justify-content:space-between;gap:20rpx;font-size:28rpx;color:#65728c;padding:4rpx 4rpx 28rpx}.record-dishes{background:#fff;border:1rpx solid #e7ebf2;border-radius:26rpx;padding:0 24rpx}.detail-item{display:flex;gap:22rpx;align-items:center;padding:24rpx 0;border-bottom:1rpx solid #edf0f5}.detail-item:last-child{border:0}.detail-item>view:last-child{flex:1;min-width:0}.detail-item text{display:block;line-height:1.6;font-size:30rpx;overflow-wrap:anywhere}.detail-item text+text{font-size:26rpx;color:#65728c;margin-top:8rpx}.record-nutrition{display:flex;justify-content:space-between;padding:28rpx 6rpx;font-size:28rpx}.record-nutrition>text:last-child{color:#65728c}.record-actions{display:flex;flex-direction:column;gap:18rpx;margin-top:14rpx}.record-actions .secondary-button{border-radius:999rpx}.correction-reason{margin-top:26rpx}.correction-reason>text{font-size:29rpx;font-weight:500}.correction-reason textarea{height:180rpx;min-height:90px;margin-bottom:0;background:#fff;font-size:28rpx}.journal-savebar{position:fixed;z-index:30;bottom:0;left:0;right:0;display:flex;gap:16rpx;background:#fff;border-top:1rpx solid #edf0f5;padding:18rpx 32rpx calc(env(safe-area-inset-bottom) + 18rpx)}.journal-savebar button{min-height:48px;border-radius:999rpx;font-size:28rpx;display:flex;align-items:center;justify-content:center}.cancel-edit{flex:.7;border:1rpx solid #cbd3e1}.save-correction{flex:1.5;background:#25262a;color:#fff}.journal button[disabled]{opacity:.45}
@media(max-width:350px){.scope-row button,.meal-head>text:last-child,.record-copy>text+text,.detail-item text+text,.record-summary,.journal-toolbar>button{font-size:13px}.record-copy>text,.meal-head,.detail-item text{font-size:14px}.journal-savebar button{font-size:14px}}
/* #ifdef H5 */
.journal-savebar{max-width:480px;margin:0 auto}
/* #endif */
</style>
